//! Vanilla-compatible admin lists (`ops.json`, `whitelist.json`, ban lists and
//! `usercache.json`).
//!
//! Ferrite has to read and write the same files as a vanilla or Paper server,
//! and round-tripping them through the server must not reformat what an
//! operator or another tool wrote. The layouts here were generated by running
//! the real 26.3 server (`/op`, `/whitelist add`, `/ban`, `/ban-ip`) and the
//! serializers reproduce its output byte for byte: two-space pretty JSON with
//! the vanilla key order and no trailing newline, except `usercache.json`,
//! which 26.3 writes compactly in `uuid`, `name`, `expiresOn` order.
//!
//! Changes are made through the four handles ([`AdminLists::ops`],
//! [`AdminLists::whitelist`], [`AdminLists::bans`], [`AdminLists::usercache`])
//! and become durable only after [`AdminLists::flush`], which rewrites just the
//! dirty files by replacing them atomically.
//!
//! # Example
//!
//! ```
//! use ferrite_admin::AdminLists;
//! use uuid::Uuid;
//!
//! # fn main() -> Result<(), Box<dyn std::error::Error>> {
//! let dir = std::env::temp_dir().join(format!("ferrite-admin-doc-{}", std::process::id()));
//! let _ = std::fs::remove_dir_all(&dir);
//! std::fs::create_dir_all(&dir)?;
//! let lists = AdminLists::load(&dir)?;
//! let uuid = Uuid::parse_str("069a79f4-44e9-4726-a5be-fca90e38aaf5")?;
//!
//! lists.ops.add_op(uuid, "TestUser", 4, false);
//! lists.whitelist.add(uuid, "TestUser");
//! lists.bans.ban(uuid, "TestUser", "griefing", "Server", None);
//! lists.usercache.cache("TestUser", uuid);
//! lists.flush()?;
//!
//! assert_eq!(lists.ops.level_of(uuid), Some(4));
//! assert!(lists.whitelist.contains_name("testuser"));
//! # Ok(())
//! # }
//! ```

#![warn(missing_docs)]

mod bans;
mod ops;
mod storage;
mod timestamp;
mod usercache;
mod whitelist;

use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, RwLock};

use uuid::Uuid;

pub use bans::{Bans, IpBan, PlayerBan};
pub use ops::Ops;
pub use timestamp::{Clock, SystemClock, Timestamp, TimestampError};
pub use usercache::UserCache;
pub use whitelist::Whitelist;

use storage::{
    BANNED_IPS_FILE, BANNED_PLAYERS_FILE, Dirty, OPS_FILE, Shared, State, USERCACHE_FILE,
    WHITELIST_FILE, read_list, serialize_compact, serialize_pretty, write_atomic,
};

/// Errors returned while loading or saving admin lists.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// A list file could not be read.
    #[error("failed to read {path}: {source}")]
    Read {
        /// File that failed.
        path: PathBuf,
        /// Underlying I/O error.
        #[source]
        source: io::Error,
    },
    /// A list file was not valid JSON in the expected shape.
    #[error("failed to parse {path}: {source}")]
    Parse {
        /// File that failed.
        path: PathBuf,
        /// Parser error, including invalid timestamps.
        #[source]
        source: serde_json::Error,
    },
    /// A list could not be serialized.
    #[error("failed to serialize {path}: {source}")]
    Serialize {
        /// File that would have been written.
        path: PathBuf,
        /// Serializer error.
        #[source]
        source: serde_json::Error,
    },
    /// Writing a list file (or renaming its temporary) failed.
    #[error("failed to write {path}: {source}")]
    Write {
        /// File that failed.
        path: PathBuf,
        /// Underlying I/O error.
        #[source]
        source: io::Error,
    },
}

/// The five vanilla admin lists for one server directory.
///
/// Loading tolerates missing files (they start empty) and ignores stale
/// `.tmp` files left behind by a crash. The struct is thread-safe: all state
/// sits behind an `RwLock`, so region threads can read it concurrently while a
/// command thread mutates or flushes it.
pub struct AdminLists {
    dir: PathBuf,
    shared: Arc<Shared>,
    /// Operator list (`ops.json`).
    pub ops: Ops,
    /// Whitelist (`whitelist.json`).
    pub whitelist: Whitelist,
    /// Player and IP bans (`banned-players.json`, `banned-ips.json`).
    pub bans: Bans,
    /// Profile name/uuid cache (`usercache.json`).
    pub usercache: UserCache,
}

impl AdminLists {
    /// Loads every list from `dir` using the machine's local clock.
    ///
    /// Missing files are treated as empty. Malformed files return
    /// [`Error::Parse`]; the other lists are not left half-loaded because the
    /// whole directory is read before the instance is built.
    pub fn load(dir: impl AsRef<Path>) -> Result<Self, Error> {
        Self::with_clock(dir, Arc::new(SystemClock))
    }

    /// Loads every list from `dir` with an injectable clock.
    ///
    /// The clock supplies `created` timestamps for new bans, `expiresOn` for
    /// cache entries and "now" for expiry checks. Existing timestamps keep
    /// their original offset.
    pub fn with_clock(dir: impl AsRef<Path>, clock: Arc<dyn Clock>) -> Result<Self, Error> {
        let dir = dir.as_ref().to_path_buf();
        let state = State {
            ops: read_list(&dir, OPS_FILE)?,
            whitelist: read_list(&dir, WHITELIST_FILE)?,
            banned_players: read_list(&dir, BANNED_PLAYERS_FILE)?,
            banned_ips: read_list(&dir, BANNED_IPS_FILE)?,
            users: read_list(&dir, USERCACHE_FILE)?,
            dirty: Dirty::default(),
        };
        let shared = Arc::new(Shared {
            state: RwLock::new(state),
            clock,
            save: Mutex::new(()),
        });
        Ok(Self {
            ops: Ops {
                shared: Arc::clone(&shared),
            },
            whitelist: Whitelist {
                shared: Arc::clone(&shared),
            },
            bans: Bans {
                shared: Arc::clone(&shared),
            },
            usercache: UserCache {
                shared: Arc::clone(&shared),
            },
            dir,
            shared,
        })
    }

    /// Directory the lists are read from and written to.
    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// Adds an operator, or updates the entry for `uuid`.
    pub fn add_op(&self, uuid: Uuid, name: &str, level: u8, bypasses_player_limit: bool) {
        self.ops.add_op(uuid, name, level, bypasses_player_limit);
    }

    /// Removes an operator, returning whether the entry existed.
    pub fn remove_op(&self, uuid: Uuid) -> bool {
        self.ops.remove_op(uuid)
    }

    /// Writes every dirty list to disk.
    ///
    /// Each file is serialized from a consistent snapshot, written to
    /// `name.json.tmp`, synced and renamed over the real file, so readers only
    /// ever see a complete old or new file. Concurrent flushes are serialized;
    /// mutations made while a flush is writing stay dirty for the next one.
    /// On failure the dirty flags are kept so the next flush retries.
    pub fn flush(&self) -> Result<(), Error> {
        let _save = storage::lock(&self.shared.save);
        let (pending, dirty) = {
            let mut state = storage::write(&self.shared.state);
            if state.dirty.is_clean() {
                return Ok(());
            }
            let dirty = state.dirty;
            let pending = Pending {
                ops: if dirty.ops {
                    Some(serialize_pretty(&self.dir, OPS_FILE, &state.ops)?)
                } else {
                    None
                },
                whitelist: if dirty.whitelist {
                    Some(serialize_pretty(
                        &self.dir,
                        WHITELIST_FILE,
                        &state.whitelist,
                    )?)
                } else {
                    None
                },
                banned_players: if dirty.banned_players {
                    Some(serialize_pretty(
                        &self.dir,
                        BANNED_PLAYERS_FILE,
                        &state.banned_players,
                    )?)
                } else {
                    None
                },
                banned_ips: if dirty.banned_ips {
                    Some(serialize_pretty(
                        &self.dir,
                        BANNED_IPS_FILE,
                        &state.banned_ips,
                    )?)
                } else {
                    None
                },
                usercache: if dirty.usercache {
                    Some(serialize_compact(&self.dir, USERCACHE_FILE, &state.users)?)
                } else {
                    None
                },
            };
            state.dirty = Dirty::default();
            (pending, dirty)
        };

        let result = self.write_pending(&pending);
        if result.is_err() {
            let mut state = storage::write(&self.shared.state);
            state.dirty.merge(dirty);
        }
        result
    }

    fn write_pending(&self, pending: &Pending) -> Result<(), Error> {
        let mut first_error = None;
        for (file, contents) in [
            (OPS_FILE, pending.ops.as_deref()),
            (WHITELIST_FILE, pending.whitelist.as_deref()),
            (BANNED_PLAYERS_FILE, pending.banned_players.as_deref()),
            (BANNED_IPS_FILE, pending.banned_ips.as_deref()),
            (USERCACHE_FILE, pending.usercache.as_deref()),
        ] {
            let Some(contents) = contents else {
                continue;
            };
            if let Err(error) = write_atomic(&self.dir.join(file), contents) {
                first_error.get_or_insert(error);
            }
        }
        match first_error {
            Some(error) => Err(error),
            None => Ok(()),
        }
    }
}

/// Serialized contents of every dirty list in one flush.
struct Pending {
    ops: Option<String>,
    whitelist: Option<String>,
    banned_players: Option<String>,
    banned_ips: Option<String>,
    usercache: Option<String>,
}
